preConditionHook:
// The canonical trading-range classification: the height of the last N bars is
// no more than K times the N-bar ATR. At the loose default (20 bars, 4.0 ATR)
// this is "the market is in a trading range"; negate the placement for "the
// market is trending", and pin it tight (15 bars, ~1.2 ATR) for a tight range.
//
// The window extremes mirror EasyLanguage's Extremes(), which Highest()/
// Lowest() call: seeded at bar 0, scanning bars 1..Length-1, strict
// comparison. Extremes is EL SOURCE, so its comparison carries the EL
// tolerance -- el_gt/el_lt, as in Breakout (the reference).
//
// `lag` (default 0, own-rules ON-30-a, 2026-11-05) reads the whole test `lag`
// bars ago: the window is bars lag .. lag + rangeLookback - 1 and the ATR is
// the value it had on bar [lag] -- EL's Highest(...)[lag] and atrVal[lag]. At
// lag 0 every number below is the one the rule computed before the input
// existed: the window starts at bar 0 and the one-slot history returns this
// bar's ATR unchanged. lag 1 is the consolidation zone BEFORE a breakout bar,
// so the breakout bar's own range does not inflate the zone's benchmark.
rangeHigh = high[(int)lag];
rangeLow = low[(int)lag];
for (int i = 1; i < (int)rangeLookback; ++i) {
    if (el_gt(high[(int)lag + i], rangeHigh)) rangeHigh = high[(int)lag + i];
    if (el_lt(low[(int)lag + i], rangeLow)) rangeLow = low[(int)lag + i];
}
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded once with a full sum on the study's first calculated bar and
// thereafter carrying S += TrueRange - TrueRange[Length], re-seeding when the
// length changes. AtrProfitTarget is the reference and carries the measurement
// notes; the two details that are load-bearing are reproduced here -- the
// re-seed on a length change (what makes it walkforward safe) and the update
// as TWO statements, because EasyLanguage evaluates S[1] + in - out left to
// right and folding it to S += in - out rounds differently.
if (atrLength != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
// EL: atrVal = WFSafe_AvgTrueRange(atrLookback); ... atrVal[lag]. A read of the
// atrVal VARIABLE's own history, which holds its initial 0 for every bar before
// the strategy's first evaluated one -- mirrored as a zero-seeded ring buffer
// of lags 0..lag (AtrRising is the reference), re-seeded if the depth changes.
if (atrHistory.size() != (std::size_t)((int)lag + 1)) {
    atrHistory.assign((std::size_t)((int)lag + 1), 0.0);
    atrCursor = 0;
}
atrHistory[atrCursor] = atr;
atrCursor = (atrCursor + 1) % atrHistory.size();
atrLagged = atrHistory[(atrCursor + atrHistory.size() - 1 - (std::size_t)(int)lag) % atrHistory.size()];
